/**
 * MCP tools server with a 2025-11-25 handshake adapter and a 2026-07-28 core.
 * Generated by Typeship — https://typeship.dev
 *
 * The protocol layer of the MCP server, shared by its stdio and HTTP
 * transports: JSON-RPC shape checks, the per-request _meta rules,
 * Streamable HTTP header validation, result wrapping, and the tool
 * surface (per-operation tools or the three-tool "meta" shape, plus the
 * search_docs / read_docs pair). Also the agent-facing contract of a tool
 * call: argument validation and coercion against the tool's input schema
 * (via ./arguments, shared with the CLI), field projection, a size cap on results,
 * and error results that carry a stable code and next steps. Transport,
 * credentials, and how a tool call reaches the API stay with the caller.
 * No external dependencies.
 *
 * Spec: https://modelcontextprotocol.io/specification/2026-07-28
 */

import { checkValue, closestName, isMeReference, normalizeName, userShapedReference, type ArgumentIssue } from "./arguments.js";
import { docsReadTarget, resolveDocsContentUrl, searchConnectedGuides } from "./docs.js";
import { projectFields, unmatchedFields, unmatchedFieldsMessage } from "./fields.js";
import { SEARCH_PAGE_SIZE, rankOperations } from "./search.js";

export { projectFields } from "./fields.js";

export const MCP_PROTOCOL_VERSION = "2026-07-28";
export const LEGACY_PROTOCOL_VERSION = "2025-11-25";
/** The modern model and the supported initialize-handshake wire revision. */
export const SUPPORTED_PROTOCOL_VERSIONS: readonly string[] = [MCP_PROTOCOL_VERSION, LEGACY_PROTOCOL_VERSION];

export const META_VERSION = "io.modelcontextprotocol/protocolVersion";
export const META_CLIENT_CAPS = "io.modelcontextprotocol/clientCapabilities";
export const META_SERVER_INFO = "io.modelcontextprotocol/serverInfo";

/** Results longer than this (in characters of JSON text) are cut down to
 * whole items or whole keys with a note saying what was left out and how to
 * ask for less. Roughly 16k tokens: under every major client's own cap, so
 * the agent sees this explanation instead of a mid-JSON chop. */
export const DEFAULT_MAX_RESULT_CHARS = 64_000;

// ---- types -----------------------------------------------------------------

export interface ServerInfo {
  name: string;
  title?: string;
  version: string;
  /** The API's docs or home page, for clients that show one. */
  websiteUrl?: string;
}

export interface ToolAnnotations {
  title?: string;
  readOnlyHint?: boolean;
  destructiveHint?: boolean;
  idempotentHint?: boolean;
  openWorldHint?: boolean;
}

export interface ToolDefinition {
  name: string;
  title?: string;
  description: string;
  inputSchema: Record<string, unknown>;
  outputSchema?: Record<string, unknown>;
  annotations?: ToolAnnotations;
}

/** A content block of a tool result (the subset this server emits). */
export type ContentBlock =
  | { type: "text"; text: string }
  | { type: "image"; data: string; mimeType: string }
  | { type: "resource"; resource: { uri: string; mimeType?: string; blob?: string; text?: string } };

/** What a tool call produced: text for every client, the JSON value behind
 * it for structuredContent, whether it is a tool execution error, and,
 * for binary results, the content blocks that replace the one text block. */
export interface ToolOutcome {
  text: string;
  isError: boolean;
  structured?: unknown;
  content?: ContentBlock[];
}

/** Throw only from an application-owned credential resolver, before calling
 * the API. The URL must show a sign-in/linking page, never a pre-authenticated
 * resource, token or personal information. The page must verify the same user
 * before linking. The runtime rechecks credentials on every subsequent call. */
export class McpAccountLinkRequired extends Error {
  readonly url: string;
  constructor(url: string) {
    super("Connect your API account in the browser to continue.");
    this.name = "McpAccountLinkRequired";
    try {
      const parsed = new URL(url);
      if (url.length > 2048 || url !== url.trim() || /[\u0000-\u0020\u007F"\\]/.test(url) || parsed.username || parsed.password || parsed.hash ||
        !(parsed.protocol === "https:" || parsed.protocol === "http:" && ["127.0.0.1", "[::1]", "localhost"].includes(parsed.hostname)) ||
        [...parsed.searchParams.keys()].some(key => /^(access_token|refresh_token|client_secret|api_key|password|authorization)$/i.test(key))) throw new Error();
    } catch { throw new Error("Provide a public HTTPS account-linking page without credentials or a fragment (HTTP loopback is allowed for development)."); }
    this.url = url;
    Object.freeze(this);
  }
}

const API_LINK_INPUT = "api_account";

/** The subset of an operation spec (ops.ts / the hosted manifest) the
 * protocol layer reads. */
export interface OpLike {
  tool: string;
  /** SDK resource and method names (accounts, list). */
  resource?: string;
  method?: string;
  httpMethod: string;
  path: string;
  summary?: string;
  description?: string;
  toolDescription: string;
  paginated: boolean;
  /** GraphQL ops accept a raw selection-set override. */
  select: boolean;
  graphql?: { kind: string; field?: string };
  params: {
    name: string;
    type: string;
    required: boolean;
    enum?: string[];
    description?: string;
    resolve?: false | ReferenceResolver;
    /** A path argument that is the Basic-auth username (Twilio's AccountSid):
     * optional, defaulting to the configured credential. `env` names the
     * variable that supplies it, when the target has one. */
    credential?: { from: "username"; env?: string };
  }[];
  inputSchema: Record<string, unknown>;
  outputSchema?: Record<string, unknown>;
  /** Canonical effect classification shared by generated docs, CLI, and MCP. */
  safety?: "read" | "write" | "destructive";
  /** Whether the operation accepts or requires an API credential. */
  auth?: "required" | "optional" | "none";
  /** The API Spec declares no security; the generic token is optional. */
  authNotDeclared?: boolean;
  /** Complete credential alternatives this runtime can send; empty when the
   * operation's only schemes are unsupported (digest, mutual TLS, …). */
  credentialOptions?: string[][];
  security?: Record<string, string[]>[];
  /** Schema-derived, valid wire arguments for examples and agent discovery. */
  exampleArguments?: Record<string, unknown>;
  /** The operation generated examples lead with: a safe read. */
  showcase?: true;
  /** Page-walking config (same shape as the SDK's PageConfig), when paginated. */
  pagination?: { style: string; itemsField: string; cursorParam?: string; idField?: string; pageParam?: string; offsetParam?: string; limitParam?: string };
  /** Success body is a text/event-stream. */
  sse?: boolean;
  /** Wire encoding of the request body. */
  bodyKind?: string | null;
  /** The spec marks the operation deprecated: search ranks it last. */
  deprecated?: boolean;
}

/** Fully proved lookup metadata carried in ops.ts / the hosted manifest. */
export interface ReferenceResolver {
  via: string;
  match: string[];
  id: string;
  idPattern?: string;
  filterParam?: string;
  inferred?: boolean;
}

/** Does the operation take a file (multipart form or raw binary body)? */
export function isUploadOp(op: OpLike): boolean {
  return op.bodyKind === "multipart" || op.bodyKind === "binary";
}

/** Ops that can be MCP tools. A tool result is one value, not a stream, so
 * event streams stay CLI/SDK-only everywhere. Uploads need a local file:
 * they are tools on a server running on the agent's machine (stdio, or a
 * locally launched HTTP server), where a file argument is a path the server
 * reads, and not on a remote endpoint, which can't see the agent's disk. */
export function mcpExposed(op: OpLike, options: { uploads?: boolean } = {}): boolean {
  if (op.sse === true) return false;
  return options.uploads === true || !isUploadOp(op);
}

export interface JsonRpcMessage {
  jsonrpc?: string;
  id?: number | string | null;
  method: string;
  params?: Record<string, unknown>;
}

/** What handleRpc hands back: the JSON-RPC message to send (null for a
 * notification) and the HTTP status the Streamable HTTP transport should
 * use for it (stdio ignores it). */
export interface RpcOutcome {
  message: Record<string, unknown> | null;
  status: number;
}

/** What the caller supplies: identity, the tool list, and how to run one. */
export interface McpServer {
  serverInfo: ServerInfo;
  /** Natural-language guidance for LLMs, returned by server/discover. */
  instructions?: string;
  /** How long clients may cache tools/list (ms). */
  toolsTtlMs: number;
  /** "public" when the tool list is the same for every caller. */
  cacheScope?: "public" | "private";
  listTools(): ToolDefinition[];
  /**
   * Run a tool. Return undefined for an unknown tool (the client gets
   * -32602), a ToolOutcome otherwise. McpAccountLinkRequired requests a
   * browser interaction; other exceptions yield -32603.
   */
  callTool(name: string, args: Record<string, unknown>): Promise<ToolOutcome | undefined>;
  /** Optional actionable wording for an unknown tool name. The protocol
   * code remains -32602; compact tool surfaces can explain how to call an
   * operation without pretending that operation is absent. */
  unknownToolMessage?(name: string): string;
  /** Called before a tool runs; a non-null outcome is sent instead
   * (rate limiting, entitlement). */
  beforeToolCall?(name: string): Promise<RpcOutcome | null> | RpcOutcome | null;
  /** Called after a tool ran, with wall time. Observability only. */
  afterToolCall?(name: string, outcome: ToolOutcome, durationMs: number): Promise<void> | void;
}

// ---- JSON-RPC shape + protocol metadata --------------------------------------

export const rpcError = (id: unknown, code: number, message: string, status: number, data?: unknown): RpcOutcome => ({
  message: { jsonrpc: "2.0", id: id ?? null, error: { code, message, ...(data !== undefined ? { data } : {}) } },
  status,
});

/** Shape check before anything else: batches (removed in 2025-06-18) and
 * non-objects get an error instead of a dead server. */
export function asJsonRpc(message: unknown): JsonRpcMessage | RpcOutcome {
  if (Array.isArray(message)) {
    return rpcError(null, -32600, "JSON-RPC batching is not supported; send one message per request.", 400);
  }
  const isObject = message !== null && typeof message === "object";
  const method = isObject ? (message as { method?: unknown }).method : undefined;
  if (!isObject || typeof method !== "string") {
    return rpcError(null, -32600, "Invalid Request: expected a JSON-RPC 2.0 message with a string method.", 400);
  }
  return message as JsonRpcMessage;
}

export function isRpcOutcome(value: JsonRpcMessage | RpcOutcome): value is RpcOutcome {
  return "status" in value;
}

/** Per-request protocol metadata (2026-07-28 basic/_meta): protocolVersion
 * and clientCapabilities are REQUIRED on every request. Missing -> -32602
 * (400 on HTTP); unsupported version -> -32022 listing what we speak. */
export function checkRequestMeta(request: JsonRpcMessage): RpcOutcome | { version: string } {
  const meta = (request.params?._meta ?? undefined) as Record<string, unknown> | undefined;
  const version = meta?.[META_VERSION];
  const caps = meta?.[META_CLIENT_CAPS];
  if (typeof version !== "string") {
    return rpcError(request.id, -32602, "Invalid params: params._meta[\"" + META_VERSION + "\"] is required on every request (MCP " + MCP_PROTOCOL_VERSION + ").", 400);
  }
  if (version !== MCP_PROTOCOL_VERSION) {
    return rpcError(request.id, -32022, "Unsupported protocol version", 400, { supported: SUPPORTED_PROTOCOL_VERSIONS, requested: version });
  }
  if (caps === null || typeof caps !== "object" || Array.isArray(caps)) {
    return rpcError(request.id, -32602, "Invalid params: params._meta[\"" + META_CLIENT_CAPS + "\"] is required on every request (MCP " + MCP_PROTOCOL_VERSION + ").", 400);
  }
  return { version };
}

/** Streamable HTTP header values may arrive as =?base64?...?= when not
 * header-safe. atob + TextDecoder: works in Node and worker runtimes alike. */
export function decodeHeaderValue(value: string): string {
  if (value.startsWith("=?base64?") && value.endsWith("?=")) {
    try {
      return new TextDecoder().decode(Uint8Array.from(atob(value.slice(9, -2)), (c) => c.charCodeAt(0)));
    } catch {
      return value;
    }
  }
  return value;
}

/** Streamable HTTP mirrors body fields into headers so intermediaries can
 * route without parsing; a server that reads the body MUST check they
 * agree (400 + -32020 HeaderMismatch), including when they're missing.
 * Notifications carry no header requirements; call this for requests. */
export function checkRequestHeaders(headers: { get(name: string): string | null }, message: JsonRpcMessage): RpcOutcome | null {
  const id = message.id;
  const version = headers.get("mcp-protocol-version");
  const bodyVersion = (message.params?._meta as Record<string, unknown> | undefined)?.[META_VERSION];
  if (message.method === "initialize" || version === LEGACY_PROTOCOL_VERSION) {
    if (bodyVersion !== undefined || headers.get("mcp-method") !== null || headers.get("mcp-name") !== null) {
      return rpcError(id, -32020, "Header mismatch: initialize-handshake requests cannot carry modern protocol metadata or routing headers.", 400);
    }
    // initialize negotiates the revision in its body, so a header naming an
    // older one is not an error here.
    return null;
  }
  if (version !== null && !SUPPORTED_PROTOCOL_VERSIONS.includes(version)) return rpcError(id, -32022, "Unsupported protocol version", 400, { supported: SUPPORTED_PROTOCOL_VERSIONS, requested: version });
  if (version === null) return rpcError(id, -32020, "Header mismatch: MCP-Protocol-Version header is required", 400);
  if (typeof bodyVersion === "string" && version !== bodyVersion) {
    return rpcError(id, -32020, "Header mismatch: MCP-Protocol-Version header '" + version + "' does not match body value '" + bodyVersion + "'", 400);
  }
  const method = headers.get("mcp-method");
  if (method === null) return rpcError(id, -32020, "Header mismatch: Mcp-Method header is required", 400);
  if (method !== message.method) {
    return rpcError(id, -32020, "Header mismatch: Mcp-Method header '" + method + "' does not match body value '" + message.method + "'", 400);
  }
  if (message.method === "tools/call") {
    const nameHeader = headers.get("mcp-name");
    const bodyName = message.params?.name;
    if (nameHeader === null) return rpcError(id, -32020, "Header mismatch: Mcp-Name header is required for tools/call", 400);
    if (typeof bodyName === "string" && decodeHeaderValue(nameHeader) !== bodyName) {
      return rpcError(id, -32020, "Header mismatch: Mcp-Name header '" + nameHeader + "' does not match body value '" + bodyName + "'", 400);
    }
  }
  return null;
}

/** Requests whose client cancelled them (stdio notifications/cancelled):
 * the spec says the server MUST NOT send further messages for them. */
const cancelled = new Set<string | number>();

/** True (and forgets the id) when a response must be suppressed. */
export function takeCancelled(id: unknown): boolean {
  return (typeof id === "string" || typeof id === "number") && cancelled.delete(id);
}

// ---- dispatch ------------------------------------------------------------------

/** One stdio process owns its handshake state. HTTP instead carries the
 * negotiated revision on each request and never needs a server session. */
export function createStdioRpcHandler(server: McpServer): (incoming: unknown) => Promise<RpcOutcome> {
  let version: string | undefined;
  let initialized = false;
  let initializing = false;
  return async (incoming) => {
    const request = asJsonRpc(incoming);
    if (isRpcOutcome(request)) return request;
    if (request.method === "initialize") {
      if (version || initializing) return rpcError(request.id, -32600, "This connection has already selected its MCP protocol.", 400, { supported: SUPPORTED_PROTOCOL_VERSIONS });
      initializing = true;
      const result = await handleRpc(server, request);
      initializing = false;
      if (result.status === 200) version = LEGACY_PROTOCOL_VERSION;
      return result;
    }
    if (version === LEGACY_PROTOCOL_VERSION) {
      if (request.method === "notifications/initialized" && request.id === undefined) initialized = true;
      if (!initialized && request.id !== undefined && request.method !== "ping") return rpcError(request.id, -32600, "Send notifications/initialized before calling MCP methods.", 400);
    } else if ((request.params?._meta as Record<string, unknown> | undefined)?.[META_VERSION] === MCP_PROTOCOL_VERSION) {
      version = MCP_PROTOCOL_VERSION;
    }
    return handleRpc(server, request, version);
  };
}

export async function handleRpc(server: McpServer, incoming: unknown, protocolVersion?: string | null): Promise<RpcOutcome> {
  const parsed = asJsonRpc(incoming);
  if (isRpcOutcome(parsed)) return parsed;
  const request = parsed;
  const id = request.id;

  // Notifications: no id, no reply. Only notifications/cancelled means anything here.
  if (id === undefined || id === null) {
    if (request.method === "notifications/cancelled") {
      const target = request.params?.requestId;
      if (typeof target === "string" || typeof target === "number") cancelled.add(target);
    }
    return { message: null, status: 202 };
  }

  // Only the wire envelope differs. Tool execution and authorization below
  // remain shared with modern clients.
  if (request.method === "initialize") {
    const params = request.params;
    if ((params?._meta as Record<string, unknown> | undefined)?.[META_VERSION] !== undefined) return rpcError(id, -32602, "initialize cannot carry modern protocol metadata.", 400);
    const info = params?.clientInfo as Record<string, unknown> | undefined;
    if (!params || typeof params.protocolVersion !== "string" || !params.capabilities || typeof params.capabilities !== "object" || Array.isArray(params.capabilities) ||
      !info || typeof info !== "object" || Array.isArray(info) || typeof info.name !== "string" || typeof info.version !== "string") {
      return rpcError(id, -32602, "initialize requires protocolVersion, capabilities, and clientInfo with name and version.", 400);
    }
    // Version negotiation: the server answers with a revision it supports
    // (the requested one when it can), and a client that cannot speak it
    // disconnects. So an older request (2025-06-18, 2025-03-26, 2024-11-05)
    // gets 2025-11-25 rather than an error.
    return { status: 200, message: { jsonrpc: "2.0", id, result: {
      protocolVersion: LEGACY_PROTOCOL_VERSION,
      capabilities: { tools: {} },
      serverInfo: server.serverInfo,
      ...(server.instructions ? { instructions: server.instructions } : {}),
    } } };
  }

  const legacy = protocolVersion === LEGACY_PROTOCOL_VERSION;
  if (legacy) {
    const meta = request.params?._meta as Record<string, unknown> | undefined;
    if (meta?.[META_VERSION] !== undefined || meta?.[META_CLIENT_CAPS] !== undefined || request.params?.inputResponses !== undefined || request.method === "server/discover") {
      return rpcError(id, -32602, "Modern protocol metadata and methods cannot be used on an initialize-handshake connection.", 400);
    }
  } else {
    const meta = checkRequestMeta(request);
    if ("status" in meta) return meta;
  }

  const complete = (result: Record<string, unknown>): RpcOutcome => ({
    message: { jsonrpc: "2.0", id, result: legacy ? result : { resultType: "complete", ...result, _meta: { [META_SERVER_INFO]: server.serverInfo } } },
    status: 200,
  });
  const cacheScope = server.cacheScope ?? "public";

  switch (request.method) {
    case "ping":
      return legacy ? complete({}) : rpcError(id, -32601, "Method not found: ping", 404);
    case "server/discover":
      return complete({
        supportedVersions: SUPPORTED_PROTOCOL_VERSIONS,
        capabilities: { tools: {} },
        ...(server.instructions ? { instructions: server.instructions } : {}),
        ttlMs: server.toolsTtlMs,
        cacheScope,
      });
    case "tools/list":
      return complete({ tools: server.listTools(), ...(!legacy ? { ttlMs: server.toolsTtlMs, cacheScope } : {}) });
    case "tools/call": {
      const name = request.params?.name;
      if (typeof name !== "string") return rpcError(id, -32602, "tools/call requires a tool name", 400);
      const args = (request.params?.arguments ?? {}) as Record<string, unknown>;
      if (args === null || typeof args !== "object" || Array.isArray(args)) {
        return rpcError(id, -32602, "tools/call arguments must be an object", 400);
      }
      const responses = request.params?.inputResponses;
      if (responses !== undefined && (responses === null || typeof responses !== "object" || Array.isArray(responses))) return rpcError(id, -32602, "inputResponses must be an object", 400);
      const response = responses && Object.hasOwn(responses, API_LINK_INPUT) ? (responses as Record<string, unknown>)[API_LINK_INPUT] : undefined;
      if (response !== undefined) {
        if (!response || typeof response !== "object" || Array.isArray(response) || !["accept", "decline", "cancel"].includes((response as { action: string }).action)) return rpcError(id, -32602, "Invalid API account-link response", 400);
        if ((response as { action: string }).action !== "accept") {
          const cancelled = textError("API account linking was cancelled. No API request was made.", "ACCOUNT_LINK_CANCELLED");
          return complete({ content: [{ type: "text", text: cancelled.text }], isError: true });
        }
        // A client acknowledgment is not authorization. Only a fresh lookup
        // of the server's linked credentials can let the operation proceed.
      }
      const denied = server.beforeToolCall ? await server.beforeToolCall(name) : null;
      if (denied) return denied;
      const started = Date.now();
      let outcome: ToolOutcome | undefined;
      try { outcome = await server.callTool(name, args); }
      catch (error) {
        if (!(error instanceof McpAccountLinkRequired)) throw error;
        const caps = legacy ? {} : (request.params?._meta as Record<string, unknown>)[META_CLIENT_CAPS] as { elicitation?: { url?: unknown } };
        const urlMode = caps.elicitation?.url;
        if (urlMode === null || typeof urlMode !== "object" || Array.isArray(urlMode)) {
          const unsupported = textError("Connect your API account using an MCP client that supports browser account-linking prompts (URL-mode elicitation), then retry.", "ACCOUNT_LINK_REQUIRED");
          return complete({ content: [{ type: "text", text: unsupported.text }], isError: true });
        }
        return { status: 200, message: { jsonrpc: "2.0", id, result: {
          resultType: "input_required",
          inputRequests: { [API_LINK_INPUT]: { method: "elicitation/create", params: { mode: "url", url: error.url, message: "Connect your API account in the browser to continue." } } },
          _meta: { [META_SERVER_INFO]: server.serverInfo },
        } } };
      }
      if (outcome === undefined) return rpcError(id, -32602, server.unknownToolMessage?.(name) ?? "Unknown tool: " + name, 400);
      if (server.afterToolCall) await server.afterToolCall(name, outcome, Date.now() - started);
      // A tool that declares an outputSchema MUST return structuredContent,
      // and clients enforce it: a successful result without it fails the
      // whole call. So every successful object result carries it, projected
      // or cut or not — the emitted outputSchema is loosened to match (no
      // `required`, no closed objects). Arrays and strings cannot be
      // structuredContent (the spec wants an object) and such tools declare
      // no outputSchema; errors keep their JSON in the text.
      const structured = outcome.structured;
      return complete({
        content: outcome.content ?? [{ type: "text", text: outcome.text }],
        ...(!outcome.isError && structured !== undefined && structured !== null && typeof structured === "object" && !Array.isArray(structured)
          ? { structuredContent: structured }
          : {}),
        isError: outcome.isError,
      });
    }
    default:
      return rpcError(id, -32601, "Method not found: " + request.method, 404);
  }
}

// ---- tool surface ---------------------------------------------------------------

/** POST operations the IR named as reads: POST /search, POST /query, and
 * friends are read-only in every way that matters to a client deciding
 * whether to ask before calling. */
const READ_METHOD_NAME = /^(list|search|query|get|find|count|lookup|retrieve|fetch|read|check|preview|validate|describe)(?![a-z])/i;
/** Mutation names that destroy or disable what they touch. */
const DESTRUCTIVE_NAME = /^(delete|remove|destroy|purge|archive|cancel|revoke|disable|deactivate|terminate|close|expire|reject)(?![a-z])/i;

/** Is this operation a read (a GET/HEAD, a GraphQL query, or a POST the
 * spec named like a search)? Drives readOnlyHint and the read-only surface. */
export function isReadOperation(op: { httpMethod: string; method?: string; graphql?: { kind: string } }): boolean {
  const m = op.httpMethod.toUpperCase();
  if (op.graphql) return op.graphql.kind === "query";
  if (m === "GET" || m === "HEAD") return true;
  return m === "POST" && op.method !== undefined && READ_METHOD_NAME.test(op.method);
}

/** Tool annotations (spec: hints, untrusted by clients). Clients such as
 * Claude Code use readOnlyHint to auto-approve reads and destructiveHint to
 * confirm writes that overwrite or remove. The server talks to one known
 * API, not the open world, so openWorldHint is false. */
export function annotationsFor(op: { httpMethod: string; summary?: string; tool: string; method?: string; graphql?: { kind: string }; safety?: "read" | "write" | "destructive" }): ToolAnnotations {
  const m = op.httpMethod.toUpperCase();
  const classified = operationSafety(op);
  const readOnly = classified === "read";
  const destructive = classified === "destructive";
  const idempotent = readOnly || m === "PUT" || m === "DELETE";
  return {
    title: op.summary ?? op.tool,
    readOnlyHint: readOnly,
    destructiveHint: destructive,
    idempotentHint: idempotent,
    openWorldHint: false,
  };
}

/** One effect vocabulary for generated references, CLI confirmation, and
 * MCP annotations. Stored on the operation manifest so every renderer says
 * the same thing even when the original operation name was unusual. */
export function operationSafety(op: { httpMethod: string; method?: string; graphql?: { kind: string }; safety?: "read" | "write" | "destructive" }): "read" | "write" | "destructive" {
  if (op.safety) return op.safety;
  if (isReadOperation(op)) return "read";
  const method = op.httpMethod.toUpperCase();
  const name = op.method ?? "";
  if (op.graphql) return DESTRUCTIVE_NAME.test(name) ? "destructive" : "write";
  return method === "DELETE" || DESTRUCTIVE_NAME.test(name)
    ? "destructive"
    : "write";
}

/** The `fields` argument every tool takes unless the API already has one:
 * dotted paths to keep in the result (per item for paginated tools). */
export const FIELDS_ARGUMENT = "fields";

function fieldsArgumentSchema(op: OpLike): Record<string, unknown> {
  return {
    type: "array",
    items: { type: "string" },
    description: "Result keys to keep, as dotted paths" + (op.paginated ? ", applied to each item" : "") + ' (e.g. ["id","name"]). Omit for the whole result. Keeps responses small.',
  };
}

/** The input schema a tool advertises: the operation's own arguments plus
 * `select` (GraphQL selection override) and `fields` (result projection)
 * when those names are free. */
export function toolInputSchema(op: OpLike): Record<string, unknown> {
  const base = op.inputSchema.properties as Record<string, unknown> | undefined;
  const properties: Record<string, unknown> = { ...(base ?? {}) };
  if (op.select && properties.select === undefined) {
    properties.select = { type: "string", description: 'GraphQL selection set override, e.g. "{ id name }"' };
  }
  if (properties[FIELDS_ARGUMENT] === undefined) properties[FIELDS_ARGUMENT] = fieldsArgumentSchema(op);
  return { ...op.inputSchema, properties };
}

/** True when the tool's own schema has a `fields` parameter, so the
 * projection argument is the API's, not ours. */
export function hasOwnFieldsParam(op: OpLike): boolean {
  return (op.inputSchema.properties as Record<string, unknown> | undefined)?.[FIELDS_ARGUMENT] !== undefined;
}

/** One tool per operation, as advertised by tools/list. */
export function operationTool(op: OpLike): ToolDefinition {
  return {
    name: op.tool,
    title: op.summary ?? op.tool,
    description: op.toolDescription,
    annotations: annotationsFor(op),
    inputSchema: toolInputSchema(op),
    ...(op.outputSchema ? { outputSchema: op.outputSchema } : {}),
  };
}

export { SEARCH_PAGE_SIZE } from "./search.js";

export const SEARCH_DOCS_TOOL: ToolDefinition = {
  name: "search_docs",
  description: "Search this API's reference (operations, parameters) and, when a docs site is configured, its guides. Best matches first; page through with page.",
  inputSchema: { type: "object", properties: { query: { type: "string", description: "The task in a few words, e.g. \"assign issue\" or \"list calls\"" }, page: { type: "integer", minimum: 1, description: "Page of reference matches (" + SEARCH_PAGE_SIZE + " per page), default 1" } }, required: ["query"] },
  annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
};

export const READ_DOCS_TOOL: ToolDefinition = {
  name: "read_docs",
  description: 'Read a documentation page: an operation reference (a tool name, or dotted "resource.method") or a docs-site guide page by name or URL. Long pages come in parts; pass the offset a part ends with to continue.',
  inputSchema: { type: "object", properties: { page: { type: "string" }, schema: { type: "boolean", description: "Also return the operation's complete input and output JSON Schemas, default false" }, offset: { type: "integer", minimum: 0, description: "Character offset to continue a long page from, default 0" } }, required: ["page"] },
  annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
};

export const EXECUTE_TOOL: ToolDefinition = {
  name: "execute",
  description: "Execute an API operation by name. Discover it with search_docs, then read_docs <operation> for its arguments, example, and safety classification. Destructive operations require confirm: true.",
  inputSchema: {
    type: "object",
    properties: {
      operation: { type: "string", description: "Operation tool name returned by search_docs" },
      arguments: { type: "object", description: "Operation arguments keyed by parameter name" },
      confirm: { type: "boolean", description: "Required and must be true for destructive operations. Omit for reads and ordinary writes." },
    },
    required: ["operation"],
  },
  annotations: { openWorldHint: false },
};

/** The keys execute itself takes; everything else is an operation argument. */
const EXECUTE_KEYS = ["operation", "arguments", "confirm"];

/** Which operations a server exposes, beyond the streams rule. */
export interface SurfaceOptions {
  /** Hide every operation that is not a read (isReadOperation). */
  readOnly?: boolean;
  /** Keep only these: resource names, tool names, or dotted resource.method. */
  include?: string[];
  /** Expose upload operations (the server runs where the files are). */
  uploads?: boolean;
}

/** The operations a server serves under these options: the callable set,
 * not just the listed one, so a hidden write is not reachable by name or
 * through execute either. Deterministic (spec) order. */
export function visibleOps<T extends OpLike>(ops: T[], options: SurfaceOptions = {}): T[] {
  let out = ops.filter((op) => mcpExposed(op, { uploads: options.uploads }));
  if (options.readOnly) out = out.filter(isReadOperation);
  if (options.include && options.include.length > 0) {
    const wanted = new Set(options.include.map((s) => s.trim().toLowerCase()).filter(Boolean));
    out = out.filter((op) => includedBy(op, wanted));
  }
  return out;
}

function includedBy(op: OpLike, wanted: Set<string>): boolean {
  return wanted.has(op.tool.toLowerCase()) ||
    (op.resource !== undefined && wanted.has(op.resource.toLowerCase())) ||
    (op.resource !== undefined && op.method !== undefined && wanted.has((op.resource + "." + op.method).toLowerCase()));
}

/** Entries of an include list that name no operation (a typo such as
 * "pull" for "pulls"). Matched against every generated operation, so an
 * entry the other switches hide still counts as a name. */
export function unmatchedIncludes(ops: OpLike[], include: string[] | undefined): string[] {
  return (include ?? []).filter((entry) => !ops.some((op) => includedBy(op, new Set([entry.trim().toLowerCase()]))));
}

/** An operation the server's own switches hide, with the reason, so a call
 * to it says why instead of reading like a typo. */
export interface HiddenOperation {
  op: OpLike;
  message: string;
  nextSteps: string[];
}

/** The exposed operations that readOnly or include hide, each explained in
 * terms of the switch the operator set (`switches` names them as the
 * operator wrote them, such as "--read-only"). */
export function hiddenOperations(ops: OpLike[], options: SurfaceOptions, switches: { readOnly: string; include: string }): HiddenOperation[] {
  const visible = new Set(visibleOps(ops, options));
  return ops.filter((op) => !visible.has(op) && mcpExposed(op, { uploads: options.uploads })).map((op) => {
    const included = !options.include?.length || includedBy(op, new Set(options.include.map((entry) => entry.trim().toLowerCase())));
    return included
      ? {
          op,
          message: op.tool + " is a write, and this server is read-only (" + switches.readOnly + "), so it cannot be called here.",
          nextSteps: ["Writes need a server started without " + switches.readOnly + "; tell the user if this operation is required."],
        }
      : {
          op,
          message: op.tool + " is not enabled on this server: " + switches.include + " limits it to " + (options.include ?? []).join(", ") + ".",
          nextSteps: ["The operation needs a server whose " + switches.include + " includes " + (op.resource ?? op.tool) + "; tell the user if it is required."],
        };
  });
}

function findHidden(source: DocsSource, wanted: string): HiddenOperation | undefined {
  const hidden = source.hiddenOps ?? [];
  const op = findOperation(hidden.map((h) => h.op), wanted);
  return op ? hidden.find((h) => h.op === op) : undefined;
}

function hiddenOutcome(hidden: HiddenOperation): ToolOutcome {
  return textError(hidden.message, "NOT_AVAILABLE", hidden.nextSteps);
}

/** Parse a comma-separated include list (from an env var or a flag). */
export function parseIncludeList(value: string | undefined | null): string[] | undefined {
  const list = (value ?? "").split(",").map((s) => s.trim()).filter(Boolean);
  return list.length > 0 ? list : undefined;
}

/**
 * The tool list for a mode: every operation plus the docs pair, or the
 * three-tool "meta" shape (search_docs, read_docs, execute) that keeps huge
 * APIs from flooding an agent's context. Deterministic order.
 */
export function toolDefinitions(ops: OpLike[], mode: "operations" | "meta", omittedOps: OpLike[] = []): ToolDefinition[] {
  if (mode === "meta") {
    const execute = structuredClone(EXECUTE_TOOL);
    const operation = (execute.inputSchema.properties as Record<string, Record<string, unknown>>).operation!;
    const example = ops.find((op) => op.showcase) ?? ops[0];
    if (example) operation.examples = [example.tool];
    const coverage = omittedOps.length > 0
      ? " This build includes " + ops.length + " of " + (ops.length + omittedOps.length) + " operations."
      : "";
    return [
      { ...SEARCH_DOCS_TOOL, description: "Search this API's " + ops.length + " generated operations and, when a docs site is configured, its guides. Start here to find the operation you need." + coverage },
      { ...READ_DOCS_TOOL, description: "Read an operation's reference (arguments, authentication, safety, an example and the result's shape) by tool name, or a docs-site guide page. schema: true adds the complete JSON Schemas." },
      execute,
    ];
  }
  return [...ops.map(operationTool), SEARCH_DOCS_TOOL, READ_DOCS_TOOL];
}


/** Resolve an operation by tool name or dotted resource.method. */
export function findOperation(ops: OpLike[], wanted: string): OpLike | undefined {
  return ops.find((o) => o.tool === wanted)
    ?? ops.find((o) => o.tool.toLowerCase() === wanted.toLowerCase().replace(/\./g, "_"));
}

/** Names of the arguments the caller must supply, given the op's params. */
export function missingArguments(op: OpLike, args: Record<string, unknown>): string[] {
  return op.params.filter((p) => p.required && args[p.name] === undefined).map((p) => p.name);
}

// ---- server instructions ----------------------------------------------------------

export interface InstructionsInput {
  title: string;
  /** Callable operations, used to advertise only capabilities the surface has. */
  ops: OpLike[];
  /** Operations the server serves (after read-only / include filtering). */
  toolCount: number;
  /** Operations present in the Definition but absent from this capped generation. */
  omittedOps?: OpLike[];
  /** Count generated before read-only or include filters narrow this server. */
  generatedOperationCount?: number;
  mode: "operations" | "meta";
  readOnly?: boolean;
  /** Write operations hidden by read-only mode. */
  hiddenWrites?: number;
  /** One sentence on where credentials come from, for this transport. */
  authHint?: string | null;
  /** The tool that returns the caller (the CLI's whoami target), when the API has one. */
  identityTool?: string | null;
  /** At least one argument accepts an exact human reference as well as an ID. */
  referenceResolution?: boolean;
  /** Upload operations are exposed (local server): their file arguments take paths. */
  uploads?: boolean;
  /** Project-supplied text, appended verbatim. */
  custom?: string | null;
}

/** The server/discover instructions: what the tools are, how arguments and
 * results behave, where credentials come from, plus whatever the project
 * adds. One paragraph; agents read it once per session. */
export function serverInstructions(input: InstructionsInput): string {
  const parts: string[] = [];
  parts.push(input.mode === "meta"
    ? input.title + " as MCP tools: search_docs, read_docs and execute over " + input.toolCount + " operations. Start with search_docs to find an operation, read_docs <tool> for its full argument reference, then execute it by name. Destructive operations require confirm: true on execute."
    : input.title + " as MCP tools: one tool per operation (" + input.toolCount + "), plus search_docs to find operations and read_docs <tool> for an operation's full argument reference.");
  if (input.omittedOps?.length) {
    const generated = input.generatedOperationCount ?? input.toolCount;
    parts.push("This build includes " + generated + " of " + (generated + input.omittedOps.length) + " operations; calling or searching for one of the others returns PLAN_LIMIT.");
  }
  parts.push("Arguments use the API's wire names; an unknown, mistyped or missing argument returns an isError result listing each problem (nothing is dropped silently), and obvious forms are coerced (\"true\" to boolean, \"3\" to number, enum case).");
  if (input.referenceResolution) parts.push("Reference arguments marked in their schema accept either an ID or an exact case-insensitive name, slug, key or email; the server resolves one match through the named list tool, reports multiple candidates, and never guesses fuzzily.");
  if (input.identityTool && input.ops.some((op) => op.params.some((param) => param.type === "string" && param.resolve !== false && userShapedReference(param.name)))) {
    parts.push("User-shaped reference arguments also accept \"me\", resolved through " + input.identityTool + ".");
  }
  parts.push("Paginated tools return items, hasMore and nextPage (the exact arguments for the following page). Pass fields (dotted paths) to keep only the result keys you need; oversized results are cut to whole items or keys with a truncated note saying how to ask for less.");
  parts.push("Errors carry error, code, message, status, the API's body and next_steps.");
  if (input.authHint) parts.push(input.authHint.trim().replace(/[.]?$/, "."));
  if (input.identityTool) parts.push("Call " + input.identityTool + " first to learn which account the credential belongs to.");
  if (input.uploads) parts.push("Upload operations take a local file path for each file argument; this server reads the file and sends it. Binary responses are saved to disk and the result names the path; images come back as an image block.");
  if (input.readOnly) {
    parts.push("This server is read-only: " + (input.hiddenWrites ? input.hiddenWrites + " write operations are not available here." : "write operations are not available here."));
  }
  if (input.custom && input.custom.trim()) parts.push(input.custom.trim());
  return parts.join(" ");
}

// ---- argument validation + coercion ---------------------------------------------

// The checks themselves live in ./arguments, shared with the CLI.
export { checkValue, closestName, coerceValue, type ArgumentIssue } from "./arguments.js";

/** Everything a tool call needs after its arguments were checked: the
 * arguments to send (coerced, projection stripped), and how to shape the
 * result. */
export interface PreparedCall {
  args: Record<string, unknown>;
  /** Dotted paths from the `fields` argument, null for the whole result. */
  fields: string[][] | null;
  /** Of those, the dotted paths a result may lack (written "?path"). */
  optionalFields: string[];
  maxChars: number;
}

/** Field paths, and which of them may be absent: a leading "?" marks a
 * path the result may lack, as reference resolution's list calls ask for
 * match keys an API can omit. Any other path must match something. */
function parseFields(value: unknown): { paths: string[][]; optional: string[] } | { error: string } {
  const raw = typeof value === "string" ? value.split(",") : Array.isArray(value) ? value : null;
  if (raw === null) return { error: "expected an array of field paths, e.g. [\"id\",\"name\"]" };
  const paths: string[][] = [];
  const optional: string[] = [];
  for (const entry of raw) {
    if (typeof entry !== "string") return { error: "expected an array of strings" };
    let path = entry.trim();
    if (path.startsWith("?")) {
      path = path.slice(1).trim();
      if (path !== "") optional.push(path);
    }
    if (path !== "") paths.push(path.split("."));
  }
  return { paths, optional };
}

/**
 * Check a tool call's arguments against the tool's input schema before
 * anything reaches the API. Unknown names are matched to the accepted one
 * when only case or punctuation differs (accountId -> account_id) and
 * rejected with a suggestion otherwise; values are coerced where the
 * intent is clear and rejected where it isn't; required arguments must be
 * present. Every problem is reported at once, as one isError result, so a
 * single round trip fixes the call. Nothing is dropped silently.
 */
export function prepareCall(
  op: OpLike,
  rawArgs: Record<string, unknown>,
  options: { maxChars?: number; credentialUsername?: string | null } = {},
): { ok: true; call: PreparedCall } | { ok: false; outcome: ToolOutcome } {
  const schema = toolInputSchema(op);
  const properties = (schema.properties ?? {}) as Record<string, Record<string, unknown>>;
  const known = Object.keys(properties);
  const issues: ArgumentIssue[] = [];
  const args: Record<string, unknown> = {};

  for (const [name, value] of Object.entries(rawArgs)) {
    if (value === undefined) continue;
    if (properties[name] !== undefined) {
      args[name] = value;
      continue;
    }
    const close = closestName(name, known);
    if (close !== undefined && normalizeName(close) === normalizeName(name) && rawArgs[close] === undefined) {
      args[close] = value;
      continue;
    }
    const accepted = known.length <= 20 ? " Accepted: " + known.join(", ") + "." : " read_docs \"" + op.tool + "\" lists the " + known.length + " accepted arguments.";
    issues.push({
      code: "UNKNOWN_ARGUMENT",
      argument: name,
      message: "Unknown argument \"" + name + "\"" + (close !== undefined ? "; did you mean \"" + close + "\"?" : ".") + accepted,
    });
  }

  let fields: string[][] | null = null;
  let optionalFields: string[] = [];
  if (!hasOwnFieldsParam(op) && args[FIELDS_ARGUMENT] !== undefined) {
    const parsed = parseFields(args[FIELDS_ARGUMENT]);
    if ("error" in parsed) issues.push({ code: "INVALID_ARGUMENT", argument: FIELDS_ARGUMENT, message: "fields: " + parsed.error });
    else if (parsed.paths.length > 0) ({ paths: fields, optional: optionalFields } = parsed);
    delete args[FIELDS_ARGUMENT];
  }

  for (const [name, value] of Object.entries(args)) {
    const propSchema = properties[name];
    if (!propSchema) continue;
    // Patterns apply inside objects and arrays. A top-level argument's own
    // pattern is left to the API: its documented example values do not all
    // satisfy it yet, and a name or "me" is only resolved to an ID later.
    args[name] = checkValue(value, propSchema, name, issues, { skipPattern: true });
  }

  // A path argument that is the configured credential's username (Twilio's
  // AccountSid) defaults to it; without one it is an ordinary missing argument
  // whose message says where the default would come from.
  for (const param of op.params) {
    if (!param.credential || args[param.name] !== undefined) continue;
    const username = options.credentialUsername ?? undefined;
    if (username !== undefined && username !== "") {
      args[param.name] = username;
      continue;
    }
    issues.push({
      code: "MISSING_ARGUMENT",
      argument: param.name,
      message: "Missing required argument \"" + param.name + "\": it defaults to the Basic-auth username" + (param.credential.env ? " (" + param.credential.env + ")" : "") + ", and none is configured. Pass " + param.name + ", or configure the credential.",
    });
  }

  const required = Array.isArray(schema.required) ? (schema.required as string[]) : [];
  for (const name of required) {
    if (args[name] === undefined) {
      issues.push({ code: "MISSING_ARGUMENT", argument: name, message: "Missing required argument \"" + name + "\"" + (properties[name]?.description ? ": " + String(properties[name]!.description).split("\n")[0] : ".") });
    }
  }

  if (issues.length > 0) return { ok: false, outcome: argumentsError(op, issues) };
  return { ok: true, call: { args, fields, optionalFields, maxChars: options.maxChars ?? DEFAULT_MAX_RESULT_CHARS } };
}

/** One caller/session's resolved names. Hosted transports must scope this
 * map by caller credential; generated stdio servers naturally have one map
 * per process. */
export type ReferenceCache = Map<string, string | number>;

export interface ResolveReferencesOptions {
  /** Operations available to act as declared/inferred resolvers. */
  ops: OpLike[];
  /** Operation returning the authenticated caller, for user-shaped "me". */
  identityTool?: string | null;
  cache: ReferenceCache;
  /** Raw operation runner: validates and calls, but does not resolve again. */
  runOperation(op: OpLike, args: Record<string, unknown>): Promise<ToolOutcome>;
  /** Hard bound for list scans. Default 5. */
  maxPages?: number;
}

export type ResolveReferencesResult =
  | { ok: true; args: Record<string, unknown> }
  | { ok: false; outcome: ToolOutcome };

function referenceError(
  code: "REFERENCE_NOT_FOUND" | "REFERENCE_AMBIGUOUS" | "REFERENCE_SCAN_LIMIT" | "NOT_AVAILABLE",
  message: string,
  argument: string,
  nextSteps: string[],
  candidates?: Record<string, unknown>[],
): ToolOutcome {
  const structured = {
    error: code === "REFERENCE_NOT_FOUND" ? "ReferenceNotFound" : code === "REFERENCE_AMBIGUOUS" ? "AmbiguousReference" : code === "REFERENCE_SCAN_LIMIT" ? "ReferenceScanLimit" : "ReferenceResolutionUnavailable",
    code,
    message,
    argument,
    ...(candidates ? { candidates } : {}),
    next_steps: nextSteps,
  };
  return { text: JSON.stringify(structured), isError: true, structured };
}

function outcomeValue(outcome: ToolOutcome): unknown {
  if (outcome.structured !== undefined) return outcome.structured;
  try { return JSON.parse(outcome.text); } catch { return undefined; }
}

function referencePage(value: unknown): { items: Record<string, unknown>[]; nextPage: Record<string, unknown> | null } | null {
  if (Array.isArray(value)) {
    return { items: value.filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === "object" && !Array.isArray(item)), nextPage: null };
  }
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  const direct = Array.isArray(record.items) ? record.items : undefined;
  const arrays = direct ? [direct] : Object.entries(record)
    .filter(([name, entry]) => name !== "request_id" && name !== "requestId" && Array.isArray(entry))
    .map(([, entry]) => entry as unknown[]);
  if (arrays.length !== 1) return null;
  return {
    items: arrays[0]!.filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === "object" && !Array.isArray(item)),
    nextPage: record.nextPage && typeof record.nextPage === "object" && !Array.isArray(record.nextPage)
      ? record.nextPage as Record<string, unknown>
      : null,
  };
}

function referenceMatchLabel(fields: string[]): string {
  return fields.length === 1 ? fields[0]! : fields.slice(0, -1).join(", ") + " or " + fields.at(-1);
}

function looksLikeIdentifier(value: string, resolver: ReferenceResolver): boolean {
  if (/\s/.test(value)) return false;
  if (resolver.idPattern !== undefined) {
    try { return new RegExp(resolver.idPattern).test(value); } catch { return false; }
  }
  return /^\d+$/.test(value) ||
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value) ||
    /^[a-z][a-z0-9]*_[a-z0-9][a-z0-9_-]*$/i.test(value) ||
    /^[A-Z][A-Z0-9]{1,9}-\d+$/.test(value) ||
    /^[A-Za-z0-9_-]{20,}$/.test(value);
}

function putReferenceCache(cache: ReferenceCache, key: string, value: string | number): void {
  cache.set(key, value);
  while (cache.size > 256) cache.delete(cache.keys().next().value!);
}

function candidateRecord(item: Record<string, unknown>, resolver: ReferenceResolver): Record<string, unknown> {
  return Object.fromEntries([resolver.id, ...resolver.match]
    .filter((name, index, all) => all.indexOf(name) === index && item[name] !== undefined)
    .map((name) => [name, item[name]]));
}

/** Resolve every eligible reference after validation/coercion and before the
 * requested API call. Matching is exact (case-insensitive for strings),
 * never fuzzy. Zero matches fail before the requested API call. */
export async function resolveReferences(
  op: OpLike,
  preparedArgs: Record<string, unknown>,
  options: ResolveReferencesOptions,
): Promise<ResolveReferencesResult> {
  const args = { ...preparedArgs };
  const maxPages = Math.max(1, Math.floor(options.maxPages ?? 5));
  const identity = options.identityTool ? findOperation(options.ops, options.identityTool) : undefined;
  /** The caller's ID for "me", fetched once per cache. */
  const callerId = async (argument: string): Promise<{ id: string | number } | { outcome: ToolOutcome }> => {
    const cacheKey = "me:" + identity!.tool;
    const cached = options.cache.get(cacheKey);
    if (cached !== undefined) return { id: cached };
    const outcome = await options.runOperation(identity!, {});
    if (outcome.isError) return { outcome };
    const body = outcomeValue(outcome);
    const id = body && typeof body === "object" && !Array.isArray(body) ? (body as Record<string, unknown>).id : undefined;
    if (typeof id !== "string" && typeof id !== "number") {
      return { outcome: referenceError("NOT_AVAILABLE", `${identity!.tool} did not return a top-level id, so "me" cannot be resolved for ${argument}.`, argument, ["Pass the caller's exact ID instead."]) };
    }
    putReferenceCache(options.cache, cacheKey, id);
    return { id };
  };
  /** "me" inside an object argument (a GraphQL input's assigneeId, or each
   * of its subscriberIds): the same resolution, keyed by property name. */
  const resolveNestedMe = async (value: unknown, key: string, path: string): Promise<{ value: unknown } | { outcome: ToolOutcome }> => {
    if (typeof value === "string") {
      if (!isMeReference(key, value)) return { value };
      const caller = await callerId(path);
      return "outcome" in caller ? caller : { value: caller.id };
    }
    if (Array.isArray(value)) {
      const items: unknown[] = [];
      for (let i = 0; i < value.length; i++) {
        const item = await resolveNestedMe(value[i], key, path + "[" + i + "]");
        if ("outcome" in item) return item;
        items.push(item.value);
      }
      return { value: items };
    }
    if (value && typeof value === "object") {
      const out: Record<string, unknown> = {};
      for (const [name, entry] of Object.entries(value as Record<string, unknown>)) {
        const resolved = await resolveNestedMe(entry, name, path + "." + name);
        if ("outcome" in resolved) return resolved;
        out[name] = resolved.value;
      }
      return { value: out };
    }
    return { value };
  };
  for (const param of op.params) {
    const raw = args[param.name];
    if (identity && raw && typeof raw === "object" && param.resolve !== false) {
      const resolved = await resolveNestedMe(raw, param.name, param.name);
      if ("outcome" in resolved) return { ok: false, outcome: resolved.outcome };
      args[param.name] = resolved.value;
      continue;
    }
    if (typeof raw !== "string" || param.resolve === false) continue;
    const value = raw.trim();

    if (identity && isMeReference(param.name, value)) {
      const caller = await callerId(param.name);
      if ("outcome" in caller) return { ok: false, outcome: caller.outcome };
      args[param.name] = caller.id;
      continue;
    }

    const resolver = param.resolve && typeof param.resolve === "object" ? param.resolve : undefined;
    if (!resolver || looksLikeIdentifier(value, resolver)) continue;
    const source = findOperation(options.ops, resolver.via);
    if (!source) continue;
    const cacheKey = source.tool + ":" + resolver.id + ":" + resolver.match.join(",") + ":" + value.toLowerCase();
    const cached = options.cache.get(cacheKey);
    if (cached !== undefined) {
      args[param.name] = cached;
      continue;
    }

    const matches = new Map<string, { id: string | number; item: Record<string, unknown> }>();
    let pageArgs: Record<string, unknown> = {};
    for (const sourceParam of source.params) {
      if (args[sourceParam.name] !== undefined && sourceParam.name !== param.name) pageArgs[sourceParam.name] = args[sourceParam.name];
    }
    if (resolver.filterParam) pageArgs[resolver.filterParam] = value;
    if (!hasOwnFieldsParam(source)) pageArgs.fields = [resolver.id, ...resolver.match.map((field) => "?" + field)];

    let exhausted = false;
    for (let pageNumber = 1; pageNumber <= maxPages; pageNumber++) {
      const outcome = await options.runOperation(source, pageArgs);
      if (outcome.isError) return { ok: false, outcome };
      const page = referencePage(outcomeValue(outcome));
      if (!page) {
        return { ok: false, outcome: referenceError("NOT_AVAILABLE", `${source.tool} did not return one recognizable item array, so ${param.name} cannot be resolved by name.`, param.name, ["Pass the exact ID instead.", `Check the resolver hint for ${source.tool}.`]) };
      }
      for (const item of page.items) {
        const id = item[resolver.id];
        if (typeof id !== "string" && typeof id !== "number") continue;
        const hit = resolver.match.some((field) => typeof item[field] === "string" && (item[field] as string).toLowerCase() === value.toLowerCase());
        if (hit) matches.set(typeof id + ":" + String(id), { id, item });
      }
      if (matches.size > 1) {
        const candidates = [...matches.values()].map(({ item }) => candidateRecord(item, resolver));
        return { ok: false, outcome: referenceError("REFERENCE_AMBIGUOUS", `${JSON.stringify(raw)} matches multiple candidates for ${param.name}; nothing was sent to ${op.tool}.`, param.name, ["Choose one candidate ID and call again."], candidates) };
      }
      if (!page.nextPage) {
        exhausted = true;
        break;
      }
      pageArgs = { ...pageArgs, ...page.nextPage };
    }
    if (!exhausted) {
      return { ok: false, outcome: referenceError("REFERENCE_SCAN_LIMIT", `${source.tool} still had more results after ${maxPages} pages, so ${JSON.stringify(raw)} could not be resolved unambiguously.`, param.name, ["Pass the exact ID instead.", `Narrow ${source.tool} with its filters, or declare a more selective resolver.`]) };
    }
    const match = [...matches.values()][0];
    if (!match) {
      return { ok: false, outcome: referenceError("REFERENCE_NOT_FOUND", `${JSON.stringify(raw)} did not exactly match any ${referenceMatchLabel(resolver.match)} from ${source.tool}; nothing was sent to ${op.tool}.`, param.name, [`Call ${source.tool} to choose an exact ${referenceMatchLabel(resolver.match)} or ID, then call again.`]) };
    }
    putReferenceCache(options.cache, cacheKey, match.id);
    args[param.name] = match.id;
  }
  return { ok: true, args };
}

/** The isError result for bad arguments: one stable code, one issue per
 * argument, and the way out. */
export function argumentsError(op: { tool: string }, issues: ArgumentIssue[]): ToolOutcome {
  const structured = {
    error: "InvalidArguments",
    code: "INVALID_ARGUMENTS",
    message: issues.length + (issues.length === 1 ? " problem" : " problems") + " with the arguments to " + op.tool + "; nothing was sent to the API.",
    issues,
    next_steps: [
      "Fix the arguments listed in issues and call " + op.tool + " again.",
      "read_docs {\"page\": \"" + op.tool + "\"} lists every argument with its type and whether it is required.",
    ],
  };
  return { text: JSON.stringify(structured), isError: true, structured };
}

// ---- results: projection, size cap, envelopes ------------------------------------

/** How a result was shaped; every field optional so callers can pass what they have. */
export interface ResultOptions {
  fields?: string[][] | null;
  maxChars?: number;
  /** Request identifier for a page that is reshaped into the MCP paging
   * envelope. Ordinary object results already retain their body field. */
  requestId?: string;
  /** For paginated results that must be cut: the op's pagination config and
   * the call's arguments let some styles resume exactly where the cut fell. */
  pagination?: OpLike["pagination"];
  args?: Record<string, unknown>;
  /** The operation's effect. When fields match nothing, a write's full
   * result rides along in the error so the agent never repeats the call to
   * see what it did. */
  safety?: "read" | "write" | "destructive";
  /** Paths the result may lack, such as a server's default projection:
   * they are left out rather than reported. */
  optionalFields?: string[];
  /** Arguments nextPage must repeat from args (required path parameters
   * such as owner and repo; fields is repeated too): the next-page
   * parameters alone, a page_url for instance, would fail validation when
   * passed back. */
  carryArgs?: string[];
}

/** A fields path that selects nothing is an error that names the keys
 * that exist, not a silent {}. The API call already happened, so the error
 * says so, and a write's unprojected result comes back with it. */
function unmatchedFieldsOutcome(value: unknown, fields: string[][] | null, perItem: boolean, options: ResultOptions): ToolOutcome | null {
  if (fields === null) return null;
  const optional = new Set(options.optionalFields ?? []);
  const unmatched = unmatchedFields(value, fields).filter((u) => !optional.has(u.path));
  if (unmatched.length === 0) return null;
  const write = options.safety !== "read";
  const maxChars = options.maxChars ?? DEFAULT_MAX_RESULT_CHARS;
  const full = write ? JSON.stringify(value) : undefined;
  const structured = {
    error: "UnmatchedFields",
    code: "FIELDS_UNMATCHED",
    message: unmatchedFieldsMessage(unmatched, perItem),
    unmatched,
    ...(full !== undefined && full.length <= maxChars / 2 ? { result: value } : {}),
    next_steps: [
      ...(write
        ? ["This operation has already run; do not call it again to change fields." + (full !== undefined && full.length <= maxChars / 2 ? " Its full result is in result." : "")]
        : ["Call again with fields from the available keys" + (perItem ? " (fields apply to each item)" : "") + ", or omit fields for the whole result."]),
    ],
  };
  return { text: JSON.stringify(structured), isError: true, structured };
}

const fieldsHint = (perItem: boolean) => "Pass fields (dotted paths" + (perItem ? ", applied per item" : "") + ") to keep only the keys you need.";

/** How many leading items fit under `budget` characters once serialized
 * compactly with commas between them. At least one. */
function itemsThatFit(items: unknown[], budget: number): number {
  let used = 0;
  let k = 0;
  for (const item of items) {
    const size = JSON.stringify(item).length + 1;
    if (k > 0 && used + size > budget) break;
    used += size;
    k++;
  }
  return Math.max(1, Math.min(k, items.length));
}

/** The result shape for a paginated tool: one page, a continuation signal,
 * and the exact arguments that fetch the next page. Over the size cap, the
 * page is cut to whole items with a `truncated` note; offset and
 * last-id styles resume at the cut, cursor and page styles say what the
 * caller must do instead. */
export function pageOutcome(items: unknown[], nextPage: Record<string, unknown> | null, options: ResultOptions = {}): ToolOutcome {
  if (nextPage !== null && options.carryArgs) {
    const args = options.args ?? {};
    const carried = options.carryArgs.filter((name) => args[name] !== undefined && !(name in nextPage!));
    nextPage = {
      ...Object.fromEntries(carried.map((name) => [name, args[name]])),
      // The same projection on the next page.
      ...(options.fields && !("fields" in nextPage) ? { fields: options.fields.map((path) => path.join(".")) } : {}),
      ...nextPage,
    };
  }
  const fields = options.fields ?? null;
  const maxChars = options.maxChars ?? DEFAULT_MAX_RESULT_CHARS;
  const unmatched = unmatchedFieldsOutcome(items, fields, true, options);
  if (unmatched) return unmatched;
  const shown = projectFields(items, fields) as unknown[];
  const full = {
    items: shown,
    hasMore: nextPage !== null,
    ...(nextPage !== null ? { nextPage } : {}),
    ...(options.requestId ? { request_id: options.requestId } : {}),
  };
  const text = JSON.stringify(full);
  if (text.length <= maxChars) {
    return { text, isError: false, structured: full };
  }

  const overhead = JSON.stringify({ items: [], hasMore: true, nextPage: nextPage ?? {}, ...(options.requestId ? { request_id: options.requestId } : {}), truncated: { omitted: 0, of: 0, reason: "x".repeat(160), next_steps: ["x".repeat(220), "x".repeat(120)] } }).length;
  const k = itemsThatFit(shown, Math.max(0, maxChars - overhead));
  const omitted = shown.length - k;
  const pg = options.pagination;
  const args = options.args ?? {};
  let resume: Record<string, unknown> | null = null;
  if (pg?.style === "offset" && pg.offsetParam) {
    const start = Number(args[pg.offsetParam]) || 0;
    resume = { ...(nextPage ?? args), [pg.offsetParam]: start + k };
  } else if (pg?.style === "cursorFromLastId" && pg.cursorParam && pg.idField) {
    const last = (items[k - 1] as Record<string, unknown> | undefined)?.[pg.idField];
    if (last !== undefined && last !== null) resume = { ...(nextPage ?? args), [pg.cursorParam]: last };
  }
  const steps: string[] = [];
  if (resume !== null) {
    steps.push("nextPage resumes at the first omitted item, so following it loses nothing.");
  } else {
    steps.push("nextPage continues after this whole page, so the omitted items are skipped by it; call again with the same arguments" + (pg?.limitParam ? " and " + pg.limitParam + "=" + k : " and a smaller page size") + " to see them.");
  }
  steps.push(fieldsHint(true));
  const structured = {
    items: shown.slice(0, k),
    hasMore: resume !== null ? true : nextPage !== null,
    ...(resume !== null ? { nextPage: resume } : nextPage !== null ? { nextPage } : {}),
    ...(options.requestId ? { request_id: options.requestId } : {}),
    truncated: {
      omitted,
      of: shown.length,
      reason: "This page is " + text.length.toLocaleString("en-US") + " characters; results are capped at " + maxChars.toLocaleString("en-US") + ". The first " + k + " of " + shown.length + " items are shown.",
      next_steps: steps,
    },
  };
  // Projected or cut, the page is still an object the loosened outputSchema
  // admits, so it is structuredContent either way.
  return { text: JSON.stringify(structured), isError: false, structured };
}

/** Placeholder for a value cut from an oversized object result. */
const omittedMarker = (key: string, chars: number, maxChars: number) => chars > maxChars
  ? "[omitted: " + chars.toLocaleString("en-US") + " characters, more than the cap on its own. Pass fields with dotted paths inside it, such as [\"" + key + ".id\"], or request a smaller page.]"
  : "[omitted: " + chars.toLocaleString("en-US") + " characters. Pass fields=[\"" + key + "\"] to fetch this key alone.]";

export function dataOutcome(data: unknown, options: ResultOptions = {}): ToolOutcome {
  const fields = options.fields ?? null;
  const maxChars = options.maxChars ?? DEFAULT_MAX_RESULT_CHARS;
  const unmatched = data !== undefined && data !== null ? unmatchedFieldsOutcome(data, fields, Array.isArray(data), options) : null;
  if (unmatched) return unmatched;
  const value = data !== undefined && data !== null ? projectFields(data, fields) : { ok: true };
  if (typeof value === "string") {
    if (value.length <= maxChars) return { text: value, isError: false, structured: value };
    return { text: value.slice(0, maxChars) + "\n\n[truncated: " + (value.length - maxChars).toLocaleString("en-US") + " more characters; results are capped at " + maxChars.toLocaleString("en-US") + ".]", isError: false };
  }
  const text = JSON.stringify(value);
  if (text.length <= maxChars) {
    return { text, isError: false, structured: value };
  }

  if (Array.isArray(value)) {
    const k = itemsThatFit(value, maxChars - 400);
    const note = "\n\n[truncated: showing " + k + " of " + value.length + " items; the result is " + text.length.toLocaleString("en-US") + " characters and results are capped at " + maxChars.toLocaleString("en-US") + ". " + fieldsHint(true) + "]";
    return { text: JSON.stringify(value.slice(0, k)) + note, isError: false };
  }
  if (typeof value === "object") {
    // Drop the largest top-level values first until it fits. A dropped key
    // is removed rather than replaced with a marker: a string where the
    // schema promised an object would fail the client's validation of
    // structuredContent. The `truncated` note names each omitted key and the
    // argument that fetches it alone.
    const entries = Object.entries(value as Record<string, unknown>).map(([key, v]) => ({ key, v, size: JSON.stringify(v)?.length ?? 4 }));
    const bySize = [...entries].sort((a, b) => b.size - a.size);
    const cut = new Map<string, number>();
    let size = text.length;
    for (const e of bySize) {
      if (size <= maxChars) break;
      cut.set(e.key, e.size);
      size -= e.size;
    }
    const out: Record<string, unknown> = {};
    for (const e of entries) if (!cut.has(e.key)) out[e.key] = e.v;
    out.truncated = {
      omitted_keys: [...cut.keys()],
      omitted: Object.fromEntries([...cut].map(([key, chars]) => [key, omittedMarker(key, chars, maxChars)])),
      reason: "The result is " + text.length.toLocaleString("en-US") + " characters; results are capped at " + maxChars.toLocaleString("en-US") + ".",
      next_steps: [fieldsHint(false)],
    };
    return { text: JSON.stringify(out), isError: false, structured: out };
  }
  return { text, isError: false, structured: value };
}

// ---- binary results -------------------------------------------------------------

/** Images up to this many bytes come back as an image content block the
 * model can look at; larger ones follow the binary path. */
export const MAX_IMAGE_BYTES = 4_000_000;
/** Without a place to save, a binary up to this size is embedded as a
 * base64 resource block; beyond it, the result describes the file. */
export const MAX_EMBED_BYTES = 1_000_000;

export interface BinaryOptions {
  /** Where a binary can be written when the server runs on the agent's
   * machine: return the saved path. Absent on remote servers. */
  saveBinary?: (bytes: Uint8Array, mediaType: string, suggestedName: string) => Promise<string> | string;
  /** Tool name, for resource URIs and file names. */
  tool?: string;
}

function toBase64(bytes: Uint8Array): string {
  const B = (globalThis as { Buffer?: { from(b: Uint8Array): { toString(e: string): string } } }).Buffer;
  if (B) return B.from(bytes).toString("base64");
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(binary);
}

const EXTENSIONS: Record<string, string> = {
  "image/png": "png", "image/jpeg": "jpg", "image/gif": "gif", "image/webp": "webp", "image/svg+xml": "svg",
  "application/pdf": "pdf", "application/zip": "zip", "application/gzip": "gz", "text/csv": "csv",
  "application/json": "json", "text/plain": "txt", "application/octet-stream": "bin",
};

/** A file extension for a media type (bin when unknown). */
export function extensionFor(mediaType: string): string {
  const base = mediaType.split(";")[0]!.trim().toLowerCase();
  return EXTENSIONS[base] ?? base.split("/")[1]?.replace(/[^a-z0-9]+/g, "") ?? "bin";
}

/**
 * A binary response as the agent should get it: an image block for images
 * the model can look at, a saved file (path, type, size) when the server
 * can write one, an embedded resource for small binaries otherwise, and
 * a description when it is too large to carry. Never "{}".
 */
export async function binaryOutcome(blob: Blob, options: BinaryOptions = {}): Promise<ToolOutcome> {
  const mediaType = (blob.type || "application/octet-stream").split(";")[0]!.trim().toLowerCase();
  const bytes = new Uint8Array(await blob.arrayBuffer());
  const name = (options.tool ?? "result") + "." + extensionFor(mediaType);
  const summary: Record<string, unknown> = { media_type: mediaType, bytes: bytes.length };
  if (mediaType.startsWith("image/") && bytes.length <= MAX_IMAGE_BYTES) {
    return {
      text: JSON.stringify(summary),
      isError: false,
      content: [{ type: "image", data: toBase64(bytes), mimeType: mediaType }, { type: "text", text: JSON.stringify(summary) }],
    };
  }
  if (options.saveBinary) {
    const path = await options.saveBinary(bytes, mediaType, name);
    const saved = { ...summary, saved_to: path, next_steps: ["The file is on the machine running this MCP server; read it from saved_to."] };
    return { text: JSON.stringify(saved), isError: false };
  }
  if (bytes.length <= MAX_EMBED_BYTES) {
    return {
      text: JSON.stringify(summary),
      isError: false,
      content: [
        { type: "resource", resource: { uri: "result://" + name, mimeType: mediaType, blob: toBase64(bytes) } },
        { type: "text", text: JSON.stringify(summary) },
      ],
    };
  }
  return {
    text: JSON.stringify({ ...summary, omitted: true, next_steps: ["The response is a " + mediaType + " of " + bytes.length.toLocaleString("en-US") + " bytes, too large to return through a remote MCP server. Fetch it with the SDK or CLI, or through the package's local MCP server, which saves binaries to disk."] }),
    isError: false,
  };
}

/** Stable codes an agent can branch on (the same vocabulary as the
 * generated CLI's error envelope). Additive only. */
export type ErrorCode =
  | "NO_AUTH" | "AUTH_INVALID" | "INSUFFICIENT_SCOPE" | "PLAN_LIMIT" | "NOT_FOUND" | "INVALID_REQUEST" | "RATE_LIMITED"
  | "SPEC_INVALID" | "SERVER_ERROR" | "NETWORK_ERROR" | "VALIDATION_FAILED" | "INVALID_ARGUMENTS" | "CONFIRMATION_REQUIRED"
  | "REFERENCE_NOT_FOUND" | "REFERENCE_AMBIGUOUS" | "REFERENCE_SCAN_LIMIT" | "NOT_AVAILABLE" | "CALL_FAILED"
  | "ACCOUNT_LINK_REQUIRED" | "ACCOUNT_LINK_CANCELLED" | "FIELDS_UNMATCHED";

export interface ErrorContext {
  /** One sentence on how to supply a credential on this transport. */
  authHint?: string | null;
  /** The API's docs site, for docs_url. */
  docsUrl?: string | null;
  /** True when a credential was sent with the request (401 means it was rejected). */
  hadCredential?: boolean;
  /** OAuth scopes the operation requires; a 403 then names them. */
  requiredScopes?: string[];
}

function rateLimitNextStep(retryAt: unknown): string {
  if (retryAt instanceof Date && !Number.isNaN(retryAt.getTime())) {
    const at = new Date(Math.ceil(retryAt.getTime() / 1000) * 1000).toISOString().replace(/\.\d{3}Z$/, "Z");
    return "Rate limited: wait until " + at + ", then call again. This is not a credential problem.";
  }
  return "Rate limited: back off, then call again once; the request already honored any Retry-After within its ceiling.";
}

/** Error codes APIs report inside a 2xx body (Slack's `error`), mapped to
 * the stable codes when their meaning is unambiguous. */
function payloadFailureCode(code: unknown): ErrorCode | undefined {
  if (typeof code !== "string") return undefined;
  if (/^(not_authed|invalid_auth|token_revoked|token_expired|account_inactive|unauthorized|unauthenticated|forbidden|access_denied|missing_scope)$/i.test(code)) return "AUTH_INVALID";
  if (/^(ratelimited|rate_limited|rate_limit_exceeded|too_many_requests)$/i.test(code)) return "RATE_LIMITED";
  return undefined;
}

/** Classify an SDK error result by status: the code and what to do next. */
export function classifyError(error: unknown, context: ErrorContext = {}): { code: ErrorCode; nextSteps: string[] } {
  const e = (error ?? {}) as { name?: string; message?: string; status?: number; code?: unknown; body?: unknown; violations?: unknown; rateLimit?: { retryAt?: Date } };
  const message = e.message ?? String(error);
  if (e.violations !== undefined) return { code: "VALIDATION_FAILED", nextSteps: ["Fix the fields named in violations and call again."] };
  if (e.name === "TransportError" || (e.name !== "PaginationError" && typeof e.status !== "number" && /fetch|ECONN|ENOTFOUND|timed out|TLS|abort/i.test(message))) {
    return { code: "NETWORK_ERROR", nextSteps: ["The API could not be reached (network, DNS, TLS or timeout). Retry once with backoff; do not loop."] };
  }
  const status = typeof e.status === "number" ? e.status : 0;
  const body = e.body as { errors?: { code?: string; message?: string }[] } | undefined;
  const auth = context.authHint ? context.authHint.trim().replace(/[.]?$/, ".") : null;
  // A rate limit can arrive as a 403 (GitHub); the SDK marks it either way.
  if (status === 429 || e.rateLimit !== undefined) return { code: "RATE_LIMITED", nextSteps: [rateLimitNextStep(e.rateLimit?.retryAt)] };
  const scopes = context.requiredScopes ?? [];
  const scopeFailure = { code: "INSUFFICIENT_SCOPE" as const, nextSteps: ["This operation requires the OAuth scopes: " + scopes.join(", ") + ". Use a credential granted them (with the CLI: login --scopes " + scopes.join(",") + "). If it already has them, the account may lack access to this resource."] };
  // A failure the API reported inside a 2xx body.
  if (e.name === "PayloadError") {
    if (scopes.length && /^missing_scope$/i.test(String(e.code))) return scopeFailure;
    const reported = payloadFailureCode(e.code);
    if (reported === "AUTH_INVALID") return { code: "AUTH_INVALID", nextSteps: ["The API rejected the credential (" + String(e.code) + ")." + (auth ? " " + auth : "")] };
    if (reported === "RATE_LIMITED") return { code: "RATE_LIMITED", nextSteps: [rateLimitNextStep(undefined)] };
    return { code: "CALL_FAILED", nextSteps: ["The API reported a failure in a successful response; body says why. Do not treat the call as done."] };
  }
  if (status === 401) {
    return context.hadCredential
      ? { code: "AUTH_INVALID", nextSteps: ["The credential was rejected; it may be expired or for another environment." + (auth ? " " + auth : "")] }
      : { code: "NO_AUTH", nextSteps: ["No credential was sent." + (auth ? " " + auth : "")] };
  }
  if (status === 403 && scopes.length) return scopeFailure;
  if (status === 403) return { code: "AUTH_INVALID", nextSteps: ["The credential lacks access to this operation; it is not a retryable error."] };
  if (status === 402) return { code: "PLAN_LIMIT", nextSteps: ["The account's plan stops here; the body may name where to lift the limit. Do not retry the same call as is."] };
  if (status === 404) return { code: "NOT_FOUND", nextSteps: notFoundNextSteps(message, e.body) };
  if (status === 422 && body?.errors?.[0]?.code === "spec_error") {
    return {
      code: "SPEC_INVALID",
      nextSteps: [
        "The API rejected the spec it was given; its error message names the invalid part.",
        context.docsUrl ? "Use search_docs with the error message, fix the spec, then call again." : "Fix the spec, then call again.",
      ],
    };
  }
  if (status === 400 || status === 409 || status === 413 || status === 422) {
    return { code: "INVALID_REQUEST", nextSteps: ["Read body for the field the API named, fix that argument and call again."] };
  }
  if (status >= 500) return { code: "SERVER_ERROR", nextSteps: ["Retry once with backoff. If it persists, report the request id from body."] };
  return { code: "CALL_FAILED", nextSteps: [] };
}

/** Keep file-path 404s actionable even when the SDK's Error.message is only
 * the OpenAPI response description and the precise message is in body. */
function notFoundNextSteps(message: string, body: unknown): string[] {
  const record = body as { errors?: { message?: unknown }[]; message?: unknown; error?: unknown } | null;
  const apiMessage = record?.errors?.[0]?.message ?? record?.message ?? record?.error;
  const combined = message + " " + (typeof apiMessage === "string" ? apiMessage : "");
  if (/\bfiles_index\b/i.test(combined)) {
    return ["Read files_index on the generation, choose an exact path it lists, then call again with that path."];
  }
  if (/\bfile\b/i.test(combined) && /\bpaths?\b/i.test(combined)) {
    return ["Check the requested file path against the API's file listing, then call again with an exact path."];
  }
  return ["Check the resource id; list the resource first to find the right one."];
}

/** A typed API error as the agent should see it: name, a stable code, the
 * message, status, the API's body, where to read more, and what to do. */
export function errorOutcome(error: unknown, context: ErrorContext = {}): ToolOutcome {
  const e = error as { name?: string; message?: string; status?: number; body?: unknown; rateLimit?: { retryAt?: Date }; response?: { requestId?: string } };
  // A GraphQL response with data and errors is a partial success: the agent
  // gets the data it can use and the errors that explain what is missing.
  const partial = error as { name?: string; data?: unknown; errors?: unknown[] } | null;
  if (partial?.name === "GraphQLRequestError" && partial.data !== undefined && partial.data !== null) {
    const structured = { data: partial.data, errors: partial.errors ?? [], partial: true };
    return { text: JSON.stringify(structured), isError: false, structured };
  }
  // The SDK raises NotModifiedError for a 304: a conditional request
  // matched. That is a result, not a failure; the CLI prints the same shape.
  const notModified = error as { name?: string; etag?: string } | null;
  if (notModified?.name === "NotModifiedError") {
    const structured = { ok: true, not_modified: true, ...(notModified.etag ? { etag: notModified.etag } : {}) };
    return { text: JSON.stringify(structured), isError: false, structured };
  }
  const { code, nextSteps } = classifyError(error, context);
  const retryAt = e?.rateLimit?.retryAt instanceof Date ? new Date(Math.ceil(e.rateLimit.retryAt.getTime() / 1000) * 1000).toISOString().replace(/\.\d{3}Z$/, "Z") : undefined;
  const bodyRequestId = e?.body && typeof e.body === "object" && !Array.isArray(e.body)
    ? (e.body as Record<string, unknown>).request_id ?? (e.body as Record<string, unknown>).requestId
    : undefined;
  const requestId = e?.response?.requestId ?? (typeof bodyRequestId === "string" ? bodyRequestId : undefined);
  const structured = {
    error: e?.name ?? "Error",
    code,
    message: e?.message,
    ...(typeof e?.status === "number" ? { status: e.status } : {}),
    ...(requestId ? { request_id: requestId } : {}),
    ...(retryAt ? { retry_at: retryAt } : {}),
    ...(e?.body !== undefined ? { body: e.body } : {}),
    ...(context.docsUrl ? { docs_url: context.docsUrl } : {}),
    next_steps: nextSteps,
  };
  return { text: JSON.stringify(structured), isError: true, structured };
}

/** A required operation whose schemes this server cannot send fails before
 * any request, instead of calling the API without credentials. */
export function unsupportedAuthOutcome(op: OpLike): ToolOutcome | null {
  if (op.auth !== "required" || !op.credentialOptions || op.credentialOptions.some((alternative) => alternative.length > 0)) return null;
  const schemes = [...new Set((op.security ?? []).flatMap((requirement) => Object.keys(requirement)))];
  return textError(`${op.tool} requires ${schemes.length ? schemes.join(" or ") : "an authentication scheme"} authentication, which this MCP server cannot send.`, "NO_AUTH", [
    "Call this operation from an SDK with a custom HTTP client that adds the credential, or ask the API owner to add a supported scheme.",
  ]);
}

export function textError(text: string, code: ErrorCode = "CALL_FAILED", nextSteps: string[] = []): ToolOutcome {
  const structured = { error: "Error", code, message: text, next_steps: nextSteps };
  return { text: JSON.stringify(structured), isError: true, structured };
}

// ---- docs tools: spec reference + docs-site prose (llms.txt) --------------------

export interface DocsSource {
  ops: OpLike[];
  /** Operations omitted from a capped generation. */
  omittedOps?: OpLike[];
  /** Operations this server's switches hide (read-only, a tools subset). */
  hiddenOps?: HiddenOperation[];
  /** Count generated before runtime surface filters. */
  generatedOperationCount?: number;
  /** Base URL of the docs site, or null when none is configured. */
  docsUrl(): string | null;
  /** Exact llms.txt URL when it is not at <docsUrl>/llms.txt. */
  docsIndexUrl?(): string | null;
  /** Fetch a URL's text, or null on any failure. */
  fetchText(url: string): Promise<string | null>;
}

async function fetchDocs(source: DocsSource, pathOrFile: string): Promise<string | null> {
  const url = resolveDocsContentUrl(source.docsUrl(), source.docsIndexUrl?.() ?? null, pathOrFile);
  return url === null ? null : source.fetchText(url);
}

/** "GraphQL mutation issueCreate" or "POST /v1/issues". */
export function operationLabel(op: Pick<OpLike, "httpMethod" | "path" | "graphql">): string {
  return op.graphql?.field ? "GraphQL " + op.graphql.kind + " " + op.graphql.field : op.httpMethod + " " + op.path;
}

function omittedEntry(op: OpLike): Record<string, string> {
  return op.graphql?.field
    ? { tool: op.tool, graphql: op.graphql.kind + " " + op.graphql.field }
    : { tool: op.tool, method: op.httpMethod, path: op.path };
}

function omittedPlanLimit(source: DocsSource, ops: OpLike[], requested?: string): ToolOutcome {
  const generated = source.generatedOperationCount ?? source.ops.length;
  const total = generated + (source.omittedOps?.length ?? 0);
  const structured = {
    error: "PlanLimitError",
    code: "PLAN_LIMIT",
    message: (requested
      ? "The operation " + requested + " is in the API but not in this package"
      : "Matching operations are in the API but not in this package") + ", which was generated with " + generated + " of its " + total + " operations.",
    omitted_operations: ops.slice(0, SEARCH_PAGE_SIZE).map(omittedEntry),
    next_steps: ["The package's publisher can regenerate it with every operation.", "Do not invent or retry an omitted operation against this package."],
  };
  return { text: JSON.stringify(structured), isError: true, structured };
}

/** Nesting read_docs spells out before pointing at schema: true. */
const REFERENCE_DEPTH = 3;
/** Characters one top-level argument's nested fields may take; a deep
 * filter object is shown shallower until it fits. */
const REFERENCE_ARGUMENT_BUDGET = 6_000;
/** Enum values listed inline; longer enums are cut with a count. */
const REFERENCE_ENUM_VALUES = 30;

/** Prose for one description: one line, markdown links reduced to their text. */
function referenceProse(text: unknown): string {
  if (typeof text !== "string") return "";
  return text.replace(/\[([^\]]*)\]\([^)]*\)/g, "$1").replace(/\s+/g, " ").trim();
}

/** Sentences the generator appends to an argument's description because a
 * call depends on them: enum meanings, defaults, deprecation, reference
 * and date forms, file paths. They survive the cut. */
const REFERENCE_NOTE = /^(Values:|Default|Deprecated|Accepts|Markdown|Paths? of (a )?local file|Must|Required|Only one of)/;
/** Leading prose kept per argument before its notes. */
const REFERENCE_ARGUMENT_PROSE = 160;

/** An argument's description, cut to its leading sentences within the
 * budget plus every note the generator added. The full text is in the
 * schema (schema: true). */
function argumentProse(text: unknown): string {
  const prose = referenceProse(text);
  if (prose.length <= REFERENCE_ARGUMENT_PROSE) return prose;
  const sentences = prose.match(/[^.!?]+(?:[.!?]+(?=\s|$)|$)\s*/g) ?? [prose];
  const kept: string[] = [];
  let used = 0;
  let cut = false;
  for (const raw of sentences) {
    const sentence = raw.trim();
    if (REFERENCE_NOTE.test(sentence)) { kept.push(sentence); continue; }
    if (kept.length === 0 || used + sentence.length <= REFERENCE_ARGUMENT_PROSE) {
      kept.push(sentence.length > REFERENCE_ARGUMENT_PROSE * 2 ? sentence.slice(0, REFERENCE_ARGUMENT_PROSE * 2).replace(/\s+\S*$/, "") + "…" : sentence);
      used += sentence.length;
    } else {
      cut = true;
    }
  }
  return kept.join(" ") + (cut ? " …" : "");
}

/** A schema's type as an agent writes it: string, integer[], "a"|"b", object. */
function referenceType(schema: Record<string, unknown>): string {
  if (Array.isArray(schema.enum)) {
    const values = schema.enum.slice(0, REFERENCE_ENUM_VALUES).map((v) => JSON.stringify(v));
    return values.join("|") + (schema.enum.length > REFERENCE_ENUM_VALUES ? "|… (" + (schema.enum.length - REFERENCE_ENUM_VALUES) + " more)" : "");
  }
  if (schema.const !== undefined) return JSON.stringify(schema.const);
  const variants = (schema.anyOf ?? schema.oneOf) as Record<string, unknown>[] | undefined;
  if (Array.isArray(variants)) return [...new Set(variants.map((v) => referenceType(v)))].join("|");
  const types = Array.isArray(schema.type) ? schema.type as string[] : typeof schema.type === "string" ? [schema.type] : [];
  const one = (t: string): string => {
    if (t === "array") {
      const items = schema.items && typeof schema.items === "object" ? referenceType(schema.items as Record<string, unknown>) : "any";
      return (/[| ]/.test(items) ? "(" + items + ")" : items) + "[]";
    }
    return t + (t === "string" && typeof schema.format === "string" ? " (" + schema.format + ")" : "");
  };
  if (types.length === 0) return schema.properties ? "object" : "any";
  return types.map(one).join("|");
}

/** The object whose fields an argument lists: itself, its array's items,
 * or the one object of a nullable union. */
function referenceObject(schema: Record<string, unknown>): Record<string, unknown> | undefined {
  if (schema.properties && typeof schema.properties === "object") return schema;
  const items = schema.items as Record<string, unknown> | undefined;
  if (items && typeof items === "object") return referenceObject(items);
  const variants = (schema.anyOf ?? schema.oneOf) as Record<string, unknown>[] | undefined;
  if (Array.isArray(variants)) {
    const objects = variants.map(referenceObject).filter((v) => v !== undefined);
    if (objects.length === 1) return objects[0];
  }
  return undefined;
}

/** One line per argument, nested fields indented beneath their object.
 * Each top-level argument is spelled out as deep as fits its budget. */
function referenceArguments(schema: Record<string, unknown>, lines: string[]): void {
  const properties = (schema.properties ?? {}) as Record<string, Record<string, unknown>>;
  for (const name of Object.keys(properties)) {
    const only = { ...schema, properties: { [name]: properties[name] } };
    let block: string[] = [];
    // Deepest first; then the same depth without listing the field names
    // below the cut; then one level with names only.
    for (const [depth, names] of [[REFERENCE_DEPTH, true], [2, true], [2, false], [1, true]] as const) {
      block = [];
      referenceArgumentLines(only, 0, depth, names, "  ", block);
      if (block.join("\n").length <= REFERENCE_ARGUMENT_BUDGET) break;
    }
    lines.push(...block);
  }
}

function referenceArgumentLines(schema: Record<string, unknown>, depth: number, maxDepth: number, names: boolean, indent: string, lines: string[]): void {
  const properties = (schema.properties ?? {}) as Record<string, Record<string, unknown>>;
  const required = new Set(Array.isArray(schema.required) ? schema.required as string[] : []);
  for (const [name, child] of Object.entries(properties)) {
    if (!child || typeof child !== "object") continue;
    const description = argumentProse(child.description);
    const extras = [
      ...(child.default !== undefined && !/\bdefault\b/i.test(description) ? ["default " + JSON.stringify(child.default)] : []),
      ...(child.deprecated === true && !/deprecated/i.test(description) ? ["deprecated"] : []),
    ];
    lines.push(indent + name + " (" + referenceType(child) + (required.has(name) ? ", required" : "") + (extras.length ? ", " + extras.join(", ") : "") + ")" + (description ? ": " + description : ""));
    const nested = referenceObject(child);
    if (!nested) continue;
    if (depth + 1 < maxDepth) {
      referenceArgumentLines(nested, depth + 1, maxDepth, names, indent + "  ", lines);
      continue;
    }
    if (!names) continue;
    const keys = Object.keys(nested.properties as object);
    lines.push(indent + "  fields: " + keys.slice(0, 40).join(", ") + (keys.length > 40 ? ", … " + (keys.length - 40) + " more" : "") + " (types with schema: true)");
  }
}

/** A result's shape in one line: keys and types, one level into objects. */
function referenceShape(schema: Record<string, unknown> | undefined, depth = 0): string {
  if (!schema || typeof schema !== "object") return "any";
  const object = schema.properties && typeof schema.properties === "object" ? schema : undefined;
  if (object) {
    if (depth >= 2) return "{…}";
    const entries = Object.entries(object.properties as Record<string, Record<string, unknown>>);
    const shown = entries.slice(0, 40).map(([key, child]) => key + ": " + referenceShape(child, depth + 1));
    return "{" + shown.join(", ") + (entries.length > 40 ? ", … " + (entries.length - 40) + " more" : "") + "}";
  }
  const items = schema.items as Record<string, unknown> | undefined;
  if (items && typeof items === "object" && (items.properties || items.items)) {
    return "[" + referenceShape(items, depth) + "]";
  }
  if (Array.isArray(schema.enum) && schema.enum.length > 8) {
    return schema.enum.slice(0, 8).map((v) => JSON.stringify(v)).join("|") + "|…";
  }
  // Nullability and formats matter for sending, not for reading a result.
  const type = referenceType({ ...schema, format: undefined });
  return type.split("|").filter((t) => t !== "null").join("|") || type;
}

/**
 * An operation's reference as read_docs returns it: what it does, whether
 * it is safe, every argument in prose (types, enums, required, notes, and
 * nested fields), one example and the result's shape. The complete JSON
 * Schemas come with `schema: true`, as the CLI's `docs --schema` does; they
 * cost several times the rest and an agent rarely needs them to call.
 */
export function referenceText(op: OpLike, options: { schema?: boolean } = {}): string {
  const safety = operationSafety(op);
  // A credential-defaulted argument (Twilio's AccountSid) is left out, so the
  // example shows the call an agent should make.
  const example = Object.fromEntries(Object.entries(op.exampleArguments ?? {})
    .filter(([name]) => !op.params.some((p) => p.name === name && p.credential)));
  const lines = [
    op.tool + ": " + operationLabel(op) + (op.paginated ? " (paginated)" : ""),
    ...(op.summary ? [op.summary] : []),
    ...(op.description && op.description.trim() !== op.summary?.trim() ? ["", op.description.trim()] : []),
    "",
    "Safety: " + safety + (safety === "destructive" ? " (execute requires confirm: true)" : ""),
    ...(op.auth ? ["Authentication: " + (op.authNotDeclared ? "not declared by the API Spec" : op.auth)] : []),
    ...(requiredScopes(op.security).length ? ["Required OAuth scopes: " + requiredScopes(op.security).join(", ")] : []),
  ];
  const input = toolInputSchema(op);
  if (Object.keys((input.properties ?? {}) as object).length > 0) {
    lines.push("", "Arguments:");
    referenceArguments(input, lines);
  }
  lines.push("", "Example arguments: " + JSON.stringify(example));
  if (op.outputSchema) {
    lines.push("", (op.paginated ? "Returns one page: " : "Returns: ") + referenceShape(op.outputSchema));
  }
  if (options.schema) {
    lines.push("", "Input schema: " + JSON.stringify(input));
    if (op.outputSchema) lines.push("", "Output schema: " + JSON.stringify(op.outputSchema));
  } else {
    lines.push("", "Full input and output JSON Schemas: read_docs " + JSON.stringify({ page: op.tool, schema: true }) + ".");
  }
  return lines.join("\n");
}

export async function docsSearch(source: DocsSource, query: string, page = 1): Promise<ToolOutcome> {
  const sections: string[] = [];
  const ranked = rankOperations(source.ops, query);
  const omittedRanked = rankOperations(source.omittedOps ?? [], query);
  const exactOmitted = findOperation(source.omittedOps ?? [], query);
  if (exactOmitted) return omittedPlanLimit(source, [exactOmitted], exactOmitted.tool);
  const pageIndex = Math.max(1, Math.floor(page)) - 1;
  const slice = ranked.slice(pageIndex * SEARCH_PAGE_SIZE, (pageIndex + 1) * SEARCH_PAGE_SIZE);
  const more = ranked.length - (pageIndex + 1) * SEARCH_PAGE_SIZE;
  if (slice.length > 0) {
    sections.push("Reference matches (best first" + (ranked.length > SEARCH_PAGE_SIZE ? ", page " + (pageIndex + 1) + " of " + Math.ceil(ranked.length / SEARCH_PAGE_SIZE) : "") + "):\n" +
      slice.map((r) => "- " + r.op.tool + ": " + searchLabel(r.op)).join("\n") +
      (more > 0 ? "\n(" + more + " more; pass page: " + (pageIndex + 2) + ")" : "") +
      "\nread_docs {\"page\": \"<tool>\"} gives an operation's arguments and example.");
  } else if (ranked.length > 0) {
    sections.push("No reference matches on page " + (pageIndex + 1) + "; there are " + Math.ceil(ranked.length / SEARCH_PAGE_SIZE) + " pages.");
  }
  const { guides, status } = await searchConnectedGuides(source.docsUrl(), source.docsIndexUrl?.() ?? null, (path) => fetchDocs(source, path), query);
  const guideSlice = guides.slice(pageIndex * SEARCH_PAGE_SIZE, (pageIndex + 1) * SEARCH_PAGE_SIZE);
  const proseMatchCount = guides.length;
  if (guideSlice.length > 0) {
    sections.push("Guide matches (best first, " + guides.length + " pages; read_docs {\"page\": \"<url>\"} reads one):\n" + guideSlice.map((match) =>
      "- [" + match.title + (match.section ? " / " + match.section : "") + "](" + match.url + "): " + match.excerpt).join("\n"));
  }
  if (status === "unavailable") sections.push("The docs site is unavailable; the API reference was still searched.");
  // Lean on purpose: the text above is what most clients show the model,
  // and this mirrors it rather than repeating the read_docs call per hit.
  const structured = {
    schema_version: "2", query, page: pageIndex + 1,
    reference: slice.map(({ op }) => ({ tool: op.tool, summary: searchLabel(op), ...(searchDeprecated(op) ? { deprecated: true } : {}) })),
    guides: guideSlice,
    totals: { reference: ranked.length, guides: guides.length }, guides_status: status,
    ...(slice.length > 0 || guideSlice.length > 0 ? { read_docs: { page: "<tool name or guide url>" } } : {}),
    ...(more > 0 ? { next_page: pageIndex + 2 } : {}),
  };
  if (omittedRanked.length > 0 && ranked.length === 0 && proseMatchCount === 0) {
    return omittedPlanLimit(source, omittedRanked.map((result) => result.op));
  }
  if (omittedRanked.length > 0) {
    const generated = source.generatedOperationCount ?? source.ops.length;
    sections.push("Also in the API but not in this package (it includes " + generated + " of " + (generated + (source.omittedOps?.length ?? 0)) + " operations; these return PLAN_LIMIT):\n" + omittedRanked.slice(0, SEARCH_PAGE_SIZE).map((result) => "- " + result.op.tool + ": " + (result.op.summary ?? operationLabel(result.op))).join("\n"));
  }
  if (sections.length === 0) {
    return {
      text: "No matches for: " + query + (source.docsUrl() === null && (source.docsIndexUrl?.() ?? null) === null ? " (a docs URL was not provided at generate time; only the API reference was searched)" : ""),
      isError: false,
      structured,
    };
  }
  return { text: sections.join("\n\n"), isError: false, structured };
}

function searchDeprecated(op: OpLike): boolean {
  return op.deprecated === true;
}

/** One line per hit: the summary (or the wire call), flagged when deprecated. */
function searchLabel(op: OpLike): string {
  return (searchDeprecated(op) ? "(deprecated) " : "") + (op.summary ?? operationLabel(op));
}

/** Characters one read_docs call returns; the rest is paged by offset. */
export const READ_DOCS_LIMIT = 20_000;

/** One part of a long page, ending with how to read the next part. */
function docsPart(page: string, text: string, offset: number, schema = false): string {
  if (offset <= 0 && text.length <= READ_DOCS_LIMIT) return text;
  const start = Math.min(Math.max(0, offset), text.length);
  const end = Math.min(text.length, start + READ_DOCS_LIMIT);
  const more = end < text.length
    ? "\n\n[Characters " + start + "-" + end + " of " + text.length + ". Continue with read_docs " + JSON.stringify({ page, ...(schema ? { schema: true } : {}), offset: end }) + ".]"
    : "\n\n[Characters " + start + "-" + end + " of " + text.length + "; end of page.]";
  return text.slice(start, end) + more;
}

export async function docsRead(source: DocsSource, page: string, offset = 0, options: { schema?: boolean } = {}): Promise<ToolOutcome> {
  const opMatch = findOperation(source.ops, page);
  if (opMatch) return { text: docsPart(page, referenceText(opMatch, options), offset, options.schema === true), isError: false };
  const omittedMatch = findOperation(source.omittedOps ?? [], page);
  if (omittedMatch) return omittedPlanLimit(source, [omittedMatch], omittedMatch.tool);
  let target = page;
  if (!/^https?:\/\//.test(target)) {
    const index = await fetchDocs(source, "llms.txt");
    target = docsReadTarget(index, source.docsUrl(), source.docsIndexUrl?.() ?? null, target);
  }
  const text = await fetchDocs(source, target);
  if (text === null) {
    return textError(source.docsUrl() === null && (source.docsIndexUrl?.() ?? null) === null
      ? "A docs URL was not provided at generate time, and no generated operation matches \"" + page + "\"."
      : "Couldn't fetch \"" + page + "\". Use search_docs to find pages.", "NOT_FOUND", ["search_docs finds operations and guide pages."]);
  }
  return { text: docsPart(page, text, offset), isError: false };
}

/**
 * Dispatch for the shared tools (search_docs, read_docs, execute); returns
 * undefined for anything else so the caller can run its own tools.
 * `runOperation` is how an execute call reaches the API; `source.ops` is
 * the callable set, so a hidden operation is unknown here too.
 */
export async function callSharedTool(
  name: string,
  args: Record<string, unknown>,
  source: DocsSource,
  runOperation: (op: OpLike, args: Record<string, unknown>) => Promise<ToolOutcome>,
): Promise<ToolOutcome | undefined> {
  if (name === "search_docs") {
    if (typeof args.query !== "string") return argumentsError({ tool: name }, [{ code: "MISSING_ARGUMENT", argument: "query", message: "search_docs requires a query string." }]);
    const page = typeof args.page === "number" ? args.page : typeof args.page === "string" && /^\d+$/.test(args.page) ? Number(args.page) : 1;
    return docsSearch(source, args.query, page);
  }
  if (name === "read_docs") {
    const offset = typeof args.offset === "number" ? args.offset : typeof args.offset === "string" && /^\d+$/.test(args.offset) ? Number(args.offset) : 0;
    const schema = args.schema === true || args.schema === "true";
    if (typeof args.page === "string" && !findOperation(source.ops, args.page)) {
      const hidden = findHidden(source, args.page);
      if (hidden) return hiddenOutcome(hidden);
    }
    return typeof args.page === "string" ? docsRead(source, args.page, offset, { schema }) : argumentsError({ tool: name }, [{ code: "MISSING_ARGUMENT", argument: "page", message: "read_docs requires a page string." }]);
  }
  if (name === "execute") {
    if (typeof args.operation !== "string") return argumentsError({ tool: name }, [{ code: "MISSING_ARGUMENT", argument: "operation", message: "execute requires an operation name." }]);
    // Operation arguments (fields included) belong inside arguments; a
    // stray top-level key would otherwise be ignored without a word.
    const stray = Object.keys(args).filter((key) => !EXECUTE_KEYS.includes(key) && args[key] !== undefined);
    if (stray.length > 0) {
      return argumentsError({ tool: name }, stray.map((key) => ({
        code: "UNKNOWN_ARGUMENT" as const,
        argument: key,
        message: "Unknown argument \"" + key + "\" to execute, which takes " + EXECUTE_KEYS.join(", ") + ". Put operation arguments, including fields, inside arguments: {\"operation\": \"" + args.operation + "\", \"arguments\": {\"" + key + "\": …}}.",
      })));
    }
    const target = findOperation(source.ops, args.operation);
    if (!target) {
      const omitted = findOperation(source.omittedOps ?? [], args.operation);
      if (omitted) return omittedPlanLimit(source, [omitted], omitted.tool);
      const hidden = findHidden(source, args.operation);
      if (hidden) return hiddenOutcome(hidden);
      const suggestions = rankOperations(source.ops, args.operation.replace(/[_.]+/g, " ")).slice(0, 3).map((r) => r.op.tool);
      return textError(
        "Unknown operation: " + args.operation + "." + (suggestions.length > 0 ? " Did you mean " + suggestions.join(", ") + "?" : ""),
        "NOT_FOUND",
        [...(suggestions.length > 0 ? ["read_docs {\"page\": \"" + suggestions[0] + "\"} gives its arguments."] : []), "search_docs finds operations by name, path or description."],
      );
    }
    if (operationSafety(target) === "destructive" && args.confirm !== true) {
      return textError(
        "The destructive operation " + target.tool + " requires explicit confirmation.",
        "CONFIRMATION_REQUIRED",
        ["Review read_docs " + target.tool + ", then retry execute with confirm: true if the destructive effect is intended."],
      );
    }
    const opArgs = args.arguments !== null && typeof args.arguments === "object" && !Array.isArray(args.arguments)
      ? (args.arguments as Record<string, unknown>)
      : {};
    return runOperation(target, opArgs);
  }
  // An operation tool the server's switches hide (operations mode).
  const hidden = source.ops.some((op) => op.tool === name) ? undefined : (source.hiddenOps ?? []).find((h) => h.op.tool === name);
  return hidden ? hiddenOutcome(hidden) : undefined;
}

/** Every OAuth scope an operation's security requirements name, in order. */
export function requiredScopes(security: Record<string, string[]>[] | undefined): string[] {
  return [...new Set((security ?? []).flatMap((requirement) => Object.values(requirement).flat()))];
}
